1. import CommonOriginal, { Hardfork } from "@ethereumjs/common";
2. import type { default as CommonType } from "@ethereumjs/common";
3. import { BN } from "ethereumjs-util";
4. import { interopImportCJSDefault } from "node-cjs-interop";
5. import { query } from "./query.js";
6. 
7. const Common = interopImportCJSDefault(CommonOriginal);
8. 
9. export async function getCommon(rpcUrl: string): Promise<CommonType> {
10.   const chainId = await query<string>(rpcUrl, "eth_chainId", []);
11. 
12.   if (!chainId) {
13.     throw new Error("getCommon: can't get result of eth_chainId");
14.   }
15. 
16.   return Common.custom({
17.     chainId: new BN(chainId.slice(2), "hex"),
18.     defaultHardfork: Hardfork.London,
19.   });
20. }
21.

