   beforeAll(() => server.listen());
   afterEach(() => server.resetHandlers());
   afterAll(() => server.close());

   describe("when return gas", () => {
     const chainId = "0x1";

     beforeEach(() => {
       server.use(
         makeHandler(rpcUrl, {
           method: "eth_chainId",
