     beforeEach(() => {
       server.use(
         makeHandler(rpcUrl, {
           method: "eth_estimateGas",
           result: null,
         })
       );
     });

     it("shoud be throw error", async () => {
       await expect(getCommon(rpcUrl)).rejects.toThrow(
         /can't get result of eth_chainId/
       );
     });
   });
 });

